<?php use LipePool\Security\Csrf; use LipePool\Support\View; ?>
<section class="page-heading container"><p class="eyebrow">Área administrativa</p><h1>Serviços</h1><p class="lead">Cadastre e mantenha o catálogo disponível para novas solicitações.</p><a class="text-link" href="/admin/agenda">← Voltar para agenda</a></section>
