    <div class="form-card service-create-card"><h2>Novo serviço</h2><form method="post" action="/admin/servicos" class="stack-form"><input type="hidden" name="_csrf" value="<?= View::escape(Csrf::token()) ?>"><label>Nome<input name="name" maxlength="120" required></label><label>Descrição <span class="muted">(opcional)</span><textarea name="description" maxlength="1000" rows="3"></textarea></label><label>Duração em minutos <span class="muted">(opcional)</span><input name="duration_minutes" type="number" min="1" max="1440"></label><button class="button button-primary" type="submit">Criar serviço</button></form></div>
